mapper.select:
SELECT cr.id, cr.user_id, cr.customer_id, cr.reminder_type, cr.title, cr.content, 
       cr.priority, cr.status, cr.due_date, cr.created_at, cr.updated_at, cr.resolution_note,
       c.name as customer_name, c.phone as customer_phone
FROM customer_reminder cr
LEFT JOIN customer c ON cr.customer_id = c.id


        AND cr.reminder_type = #{type}


        AND cr.status = #{status}


        AND cr.user_id = #{userId}


ORDER BY cr.due_date ASC

SELECT cr.id, cr.user_id, cr.customer_id, cr.reminder_type, cr.title, cr.content, cr.priority, cr.status, cr.due_date, cr.created_at, cr.updated_at, cr.resolution_note, c.name as customer_name, c.phone as customer_phone FROM customer_reminder cr LEFT JOIN customer c ON cr.customer_id = c.id
cr.customer_id = #{customerId}
AND cr.user_id = #{userId}
ORDER BY cr.due_date ASC

mapper.update:
UPDATE knowledge_article
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE customer_reminder
SET status = 'RESOLVED', updated_at = NOW()

    , resolution_note = #{note}

WHERE id = #{reminderId}

    AND user_id = #{userId}

mapper.delete:
DELETE FROM customer_reminder
WHERE id = #{id}

    AND user_id = #{userId}
